  def numpy_to_gsl_vector(np_array):
    return gsl.gsl_vector_from_array(array(np_array))
  A_gsl = numpy_to_gsl_matrix(A)
  B_gsl = numpy_to_gsl_matrix(B)
  workspace = gsl.gsl_eigen_gensymm_workspace_alloc(len(A))
  eigenvalues = (gsl.gsl_vector * len(A))()
  result = gsl.compute_gensymm_eigenvalues(A_gsl, B_gsl, workspace, eigenvalues)
