class GSLMatrix(object):
    def __init__(self, data):
        self._matrix = gsl.gsl_matrix_create(len(data), len(data[0]))
        for i in range(len(data)):
            for j in range(len(data[0])):
                gsl.gsl_matrix_set(self._matrix, i, j, data[i][j])
    def __repr__(self):
        rows = gsl.gsl_matrix_get_size(self._matrix)[0]
        cols = gsl.gsl_matrix_get_size(self._matrix)[1]
        data = []
        for i in range(rows):
            row = []
            for j in range(cols):
                row.append(gsl.gsl_matrix_get(self._matrix, i, j))
            data.append(row)
        return data
    def free(self):
        gsl.gsl_matrix_free(self._matrix)

def create_gsl_matrix(data):
    return GSLMatrix(data)

def retrieve_gsl_matrix(gsl_matrix):
