    matrix_ptr = gsl.gsl_matrix_alloc(num_rows, num_cols)
    for i in range(num_rows):
        for j in range(num_cols):
            matrix_ptr[i, j] = matrix[i][j]
    return matrix_ptr

def vector_to_gsl(vector: List[float]) -> gsl.gsl_vector *:
    vector_ptr = gsl.gsl_vector_alloc(len(vector))
    for i in range(len(vector)):
        vector_ptr[i] = vector[i]
