def gsl_bspline_init_greville(abscissae):
    vector = GslVector(data=ctypes.cast(ctypes.byref(abscissae), ctypes.POINTER(ctypes.c_double)), size=len(abscissae), stride=1)
    workspace = gsl.gsl_bspline_workspace_alloc(len(abscissae) - 1, 3)
    success_code = gsl.init_bspline_greville(workspace, vector, 3)
